    runtime.syncOverlay()
    if(runtime.find.render())return
    const aq=Boolean(runtime.data.aq_mode)
    runtime.overlay.toggleAttribute("data-aq-mode",aq)
    runtime.input.placeholder=aq?"NUMO or AQ search":"Title, author, phrase or axiom ID"
    runtime.input.setAttribute("aria-label",aq?"Search AQ":"Search CARE books, passages, axioms, NUMO and AQ")
    const query=String(runtime.data?.query||"")
    if(!runtime.open&&runtime.input.value!==query)runtime.input.value=query
    const settled=runtime.isSettled()
    runtime.root.classList.toggle("searching",runtime.open&&!settled)
    if(!settled&&runtime.open&&runtime.timer===null)runtime.scheduleQuery()
    const corrected=String(runtime.data?.corrected_query||"")
    const filters=Array.isArray(runtime.data?.filters)?runtime.data.filters:[]
    const notes=[...filters]
    if(corrected&&corrected.toLowerCase()!==query.toLowerCase())notes.push(`Close spelling · ${corrected}`)
    if(runtime.data?.indexing)notes.push("Preparing the full text index…")
    runtime.correction.hidden=!notes.length
    runtime.correction.textContent=notes.join("  ·  ")
    const previous=runtime.results.querySelector(`[data-index="${runtime.selectedIndex}"]`)?.dataset.identity
    runtime.results.replaceChildren()
    const rows=runtime.rows()
    rows.forEach((item,index)=>{
      const button=document.createElement("button");button.type="button";button.className="csp-result";button.role="option";button.tabIndex=-1;button.dataset.index=String(index);button.id=`care-spotlight-result-${index}`
      button.dataset.identity=item.identity
      const card=item.presentation
      const content=document.createElement("span");content.className="care-search-card";content.dataset.tone=card.tone
      const head=document.createElement("span");head.className="care-search-card-head"
      cardField(head,"badge",card.badge);cardField(head,"reason",card.reason);content.append(head)
      cardField(content,"title",card.title);cardField(content,"meta",card.meta)
      cardField(content,"context",card.heading)
      cardField(content,"snippet",card.snippet);cardField(content,"ref",card.reference)
      button.append(content);runtime.results.append(button)
    })
